import{_ as t,c as e,o as a,a0 as o}from"./chunks/framework.DKRgXLPU.js";const r=JSON.parse('{"title":"Modelo de Diário de Treinamento","description":"","frontmatter":{},"headers":[],"relativePath":"pt/diary-template.md","filePath":"pt/diary-template.md"}');const i=t({name:"pt/diary-template.md"},[["render",function(t,r,i,s,n,d){return a(),e("div",null,[...r[0]||(r[0]=[o('<h1 id="modelo-de-diario-de-treinamento" tabindex="-1">Modelo de Diário de Treinamento <a class="header-anchor" href="#modelo-de-diario-de-treinamento" aria-label="Permalink to &quot;Modelo de Diário de Treinamento&quot;">​</a></h1><h2 id="como-usar-este-modelo" tabindex="-1">Como usar este modelo <a class="header-anchor" href="#como-usar-este-modelo" aria-label="Permalink to &quot;Como usar este modelo&quot;">​</a></h2><p>Um diário de treino é o seu registro pessoal de prática, progresso e percepções. Ele ajuda você a acompanhar o que funciona, identificar padrões e acelerar a melhoria. Copie as seções abaixo para o formato de sua preferência (Word, Google Docs, Excel, Google Sheets ou um caderno).</p><div class="tip custom-block"><p class="custom-block-title">O Poder da Reflexão</p><p><strong>O que é medido é aprimorado. O que é refletido é dominado.</strong> Um diário de treinamento transforma a prática aleatória em desenvolvimento deliberado.</p></div><h2 id="modelo-de-registro-de-treinamento-diario" tabindex="-1">Modelo de Registro de Treinamento Diário <a class="header-anchor" href="#modelo-de-registro-de-treinamento-diario" aria-label="Permalink to &quot;Modelo de Registro de Treinamento Diário&quot;">​</a></h2><h3 id="copie-esta-secao-para-cada-sessao-de-treinamento" tabindex="-1">Copie esta seção para cada sessão de treinamento <a class="header-anchor" href="#copie-esta-secao-para-cada-sessao-de-treinamento" aria-label="Permalink to &quot;Copie esta seção para cada sessão de treinamento&quot;">​</a></h3><hr><p><strong>Date:</strong> ________ <strong>Time:</strong> ________ to ________ <strong>Duration:</strong> ________ minutes <strong>Location:</strong> ________ <strong>Terrain:</strong> Hard / Medium / Soft / Mixed <strong>Weather:</strong> Sunny / Cloudy / Windy / Rain</p><h3 id="training-partners" tabindex="-1">Training Partners <a class="header-anchor" href="#training-partners" aria-label="Permalink to &quot;Training Partners&quot;">​</a></h3><ul><li></li><li></li><li></li></ul><h3 id="today-s-intention" tabindex="-1">Today&#39;s Intention <a class="header-anchor" href="#today-s-intention" aria-label="Permalink to &quot;Today&#39;s Intention&quot;">​</a></h3><p>(What was my main focus for this session?)</p><hr><h3 id="pratica-tecnica" tabindex="-1">Prática Técnica <a class="header-anchor" href="#pratica-tecnica" aria-label="Permalink to &quot;Prática Técnica&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Habilidade praticada</th><th>Repetições/Tempo</th><th>Taxa de sucesso</th><th>Observações</th></tr></thead><tbody><tr><td><strong>Apontando</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Filmagem</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Leitura do Terreno</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Seleção de Fotos</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="o-que-funcionou-bem" tabindex="-1">O que funcionou bem? <a class="header-anchor" href="#o-que-funcionou-bem" aria-label="Permalink to &quot;O que funcionou bem?&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="o-que-precisa-ser-melhorado" tabindex="-1">O que precisa ser melhorado? <a class="header-anchor" href="#o-que-precisa-ser-melhorado" aria-label="Permalink to &quot;O que precisa ser melhorado?&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="principais-conclusoes" tabindex="-1">Principais conclusões <a class="header-anchor" href="#principais-conclusoes" aria-label="Permalink to &quot;Principais conclusões&quot;">​</a></h3><p>(Uma das principais lições aprendidas hoje)</p><hr><h3 id="mental-game" tabindex="-1">Mental Game <a class="header-anchor" href="#mental-game" aria-label="Permalink to &quot;Mental Game&quot;">​</a></h3><p><strong>Energy Level (1-10):</strong> _____ <strong>Focus Quality (1-10):</strong> _____ <strong>Confidence (1-10):</strong> _____</p><p><strong>Mental Challenges Today:</strong></p><p><strong>How I Handled Them:</strong></p><p><strong>Mental Technique Practiced:</strong></p><ul><li>[ ] 3-Breath Reset</li><li>[ ] Inner Coach Reframe</li><li>[ ] Mindful Awareness</li><li>[ ] Visualization</li><li>[ ] Other: ________</li></ul><hr><h3 id="condicao-fisica" tabindex="-1">Condição Física <a class="header-anchor" href="#condicao-fisica" aria-label="Permalink to &quot;Condição Física&quot;">​</a></h3><p><strong>Sensação corporal (1-10):</strong> _____ <strong>Qualquer dor/desconforto:</strong> _____ <strong>Nível de fadiga (1-10):</strong> _____</p><p><strong>Observações Físicas:</strong></p><hr><h3 id="tomorrow-s-focus" tabindex="-1">Tomorrow&#39;s Focus <a class="header-anchor" href="#tomorrow-s-focus" aria-label="Permalink to &quot;Tomorrow&#39;s Focus&quot;">​</a></h3><p>(Based on today, what will I work on next session?)</p><hr><h2 id="modelo-de-inscricao-para-competicao-partida" tabindex="-1">Modelo de Inscrição para Competição/Partida <a class="header-anchor" href="#modelo-de-inscricao-para-competicao-partida" aria-label="Permalink to &quot;Modelo de Inscrição para Competição/Partida&quot;">​</a></h2><h3 id="copie-esta-secao-para-cada-competicao" tabindex="-1">Copie esta seção para cada competição <a class="header-anchor" href="#copie-esta-secao-para-cada-competicao" aria-label="Permalink to &quot;Copie esta seção para cada competição&quot;">​</a></h3><hr><p><strong>Date:</strong> ________ <strong>Tournament:</strong> ________ <strong>Format:</strong> Triples / Doubles / Singles <strong>Team:</strong> ________</p><h3 id="pre-competition" tabindex="-1">Pre-Competition <a class="header-anchor" href="#pre-competition" aria-label="Permalink to &quot;Pre-Competition&quot;">​</a></h3><p><strong>Sleep Quality (1-10):</strong> _____ <strong>Nutrition:</strong> _____ <strong>Mental State (1-10):</strong> _____ <strong>Physical Warm-up:</strong> Yes / No <strong>Mental Warm-up:</strong> Yes / No</p><hr><h3 id="resultados-da-partida" tabindex="-1">Resultados da Partida <a class="header-anchor" href="#resultados-da-partida" aria-label="Permalink to &quot;Resultados da Partida&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rodada</th><th>Adversário</th><th>Placar</th><th>Resultado</th><th>Momentos-chave</th></tr></thead><tbody><tr><td><strong>1</strong></td><td></td><td></td><td>V / D</td><td></td></tr><tr><td><strong>2</strong></td><td></td><td></td><td>V / D</td><td></td></tr><tr><td><strong>3</strong></td><td></td><td></td><td>V / D</td><td></td></tr><tr><td><strong>4</strong></td><td></td><td></td><td>V / D</td><td></td></tr></tbody></table><p><strong>Classificação final:</strong> _____</p><hr><h3 id="performance-analysis" tabindex="-1">Performance Analysis <a class="header-anchor" href="#performance-analysis" aria-label="Permalink to &quot;Performance Analysis&quot;">​</a></h3><p><strong>Technical Performance (1-10):</strong> _____ <strong>Mental Performance (1-10):</strong> _____ <strong>Tactical Decisions (1-10):</strong> _____ <strong>Team Communication (1-10):</strong> _____</p><h3 id="what-i-did-well" tabindex="-1">What I Did Well <a class="header-anchor" href="#what-i-did-well" aria-label="Permalink to &quot;What I Did Well&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="what-cost-me-points" tabindex="-1">What Cost Me Points <a class="header-anchor" href="#what-cost-me-points" aria-label="Permalink to &quot;What Cost Me Points&quot;">​</a></h3><ol><li></li><li></li></ol><h2 id="monthly-summary-template" tabindex="-1">Monthly Summary Template <a class="header-anchor" href="#monthly-summary-template" aria-label="Permalink to &quot;Monthly Summary Template&quot;">​</a></h2><h3 id="copy-this-section-each-month" tabindex="-1">Copy This Section Each Month <a class="header-anchor" href="#copy-this-section-each-month" aria-label="Permalink to &quot;Copy This Section Each Month&quot;">​</a></h3><hr><p><strong>Mês:</strong> ________ <strong>Ano:</strong> ________</p><h3 id="estatisticas-mensais" tabindex="-1">Estatísticas Mensais <a class="header-anchor" href="#estatisticas-mensais" aria-label="Permalink to &quot;Estatísticas Mensais&quot;">​</a></h3><p><strong>Total de horas de treinamento:</strong> _____ <strong>Total de sessões:</strong> _____ <strong>Competições em que participou:</strong> _____ <strong>Taxa de vitórias:</strong> _____%</p><h3 id="progresso-tecnico" tabindex="-1">Progresso Técnico <a class="header-anchor" href="#progresso-tecnico" aria-label="Permalink to &quot;Progresso Técnico&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Habilidade</th><th>Início do mês</th><th>Fim do mês</th><th>Melhoria</th></tr></thead><tbody><tr><td><strong>Precisão de apontamento</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Consistência nos disparos</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Adaptação ao Terreno</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Seleção de Fotos</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="progresso-no-jogo-mental" tabindex="-1">Progresso no Jogo Mental <a class="header-anchor" href="#progresso-no-jogo-mental" aria-label="Permalink to &quot;Progresso no Jogo Mental&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Área</th><th>Início do mês</th><th>Fim do mês</th><th>Melhoria</th></tr></thead><tbody><tr><td><strong>Gestão de Pressão</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Foco na Qualidade</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Confiança</strong></td><td></td><td></td><td></td></tr><tr><td><strong>Utilização do Coach Interior</strong></td><td></td><td></td><td></td></tr></tbody></table><h3 id="destaques-do-mes" tabindex="-1">Destaques do mês <a class="header-anchor" href="#destaques-do-mes" aria-label="Permalink to &quot;Destaques do mês&quot;">​</a></h3><p><strong>Melhor sessão de treinamento:</strong></p><p><strong>Melhor desempenho na competição:</strong></p><p><strong>Principal avanço:</strong></p><p><strong>Aprendizado mais valioso:</strong></p><h3 id="desafios-superados" tabindex="-1">Desafios Superados <a class="header-anchor" href="#desafios-superados" aria-label="Permalink to &quot;Desafios Superados&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="desafios-continuos" tabindex="-1">Desafios contínuos <a class="header-anchor" href="#desafios-continuos" aria-label="Permalink to &quot;Desafios contínuos&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="prioridades-do-proximo-mes" tabindex="-1">Prioridades do próximo mês <a class="header-anchor" href="#prioridades-do-proximo-mes" aria-label="Permalink to &quot;Prioridades do próximo mês&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><hr><h2 id="specific-practice-tracking-templates" tabindex="-1">Specific Practice Tracking Templates <a class="header-anchor" href="#specific-practice-tracking-templates" aria-label="Permalink to &quot;Specific Practice Tracking Templates&quot;">​</a></h2><h3 id="pointing-practice-log" tabindex="-1">Pointing Practice Log <a class="header-anchor" href="#pointing-practice-log" aria-label="Permalink to &quot;Pointing Practice Log&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>Distance</th><th>Terrain</th><th>Attempts</th><th>Within 10cm</th><th>Within 20cm</th><th>Within 50cm</th><th>Notes</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Instructions:</strong></p><ul><li>Track pointing accuracy at different distances (6m, 7m, 8m, 9m, 10m)</li><li>Record terrain type (hard, medium, soft)</li><li>Count successes in each distance range</li><li>Calculate success rate over time</li></ul><hr><h3 id="registro-de-pratica-de-tiro" tabindex="-1">Registro de Prática de Tiro <a class="header-anchor" href="#registro-de-pratica-de-tiro" aria-label="Permalink to &quot;Registro de Prática de Tiro&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Data</th><th>Tipo de Alvo</th><th>Distância</th><th>Tentativas</th><th>Acertos Diretos</th><th>Carreau</th><th>Deslocamento</th><th>Observações</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Tipos de alvos:</strong></p><ul><li>Bola estática</li><li>Bola contra cochonnet</li><li>Bola em aglomerado</li><li>Alvo móvel (avançado)</li></ul><hr><h3 id="mental-training-log" tabindex="-1">Mental Training Log <a class="header-anchor" href="#mental-training-log" aria-label="Permalink to &quot;Mental Training Log&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>Technique Practiced</th><th>Duration</th><th>Situation</th><th>Effectiveness (1-10)</th><th>Notes</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Techniques:</strong></p><ul><li>3-Breath Reset</li><li>Inner Coach Reframe</li><li>Visualization</li><li>Mindfulness Practice</li><li>Pre-shot Routine</li><li>Pressure Simulation</li></ul><hr><h2 id="registro-diario-rapido-simplificado" tabindex="-1">Registro Diário Rápido (Simplificado) <a class="header-anchor" href="#registro-diario-rapido-simplificado" aria-label="Permalink to &quot;Registro Diário Rápido (Simplificado)&quot;">​</a></h2><h3 id="para-dias-corridos-copie-este-modelo-minimalista" tabindex="-1">Para dias corridos - Copie este modelo minimalista <a class="header-anchor" href="#para-dias-corridos-copie-este-modelo-minimalista" aria-label="Permalink to &quot;Para dias corridos - Copie este modelo minimalista&quot;">​</a></h3><hr><p><strong>Date:</strong> ________</p><p><strong>Trained:</strong> Yes / No <strong>Duration:</strong> _____ min <strong>Focus:</strong> ________ <strong>Energy (1-10):</strong> _____ <strong>Quality (1-10):</strong> _____</p><p><strong>One Win:</strong></p><p><strong>One Learning:</strong></p><p><strong>Tomorrow&#39;s Focus:</strong></p><hr><h2 id="sugestoes-para-reflexao" tabindex="-1">Sugestões para reflexão <a class="header-anchor" href="#sugestoes-para-reflexao" aria-label="Permalink to &quot;Sugestões para reflexão&quot;">​</a></h2><p>Use essas sugestões para aprofundar suas anotações no diário:</p><h3 id="apos-o-treinamento" tabindex="-1">Após o Treinamento <a class="header-anchor" href="#apos-o-treinamento" aria-label="Permalink to &quot;Após o Treinamento&quot;">​</a></h3><ol><li>O que me surpreendeu hoje?</li><li>Quando me senti mais confiante?</li><li>Quando tive dificuldades? Por quê?</li><li>O que eu faria de diferente?</li><li>Pelo que sou grato(a) nesta sessão?</li></ol><h3 id="apos-a-competicao" tabindex="-1">Após a Competição <a class="header-anchor" href="#apos-a-competicao" aria-label="Permalink to &quot;Após a Competição&quot;">​</a></h3><ol><li>O que aprendi sobre mim hoje?</li><li>Como lidei com a pressão?</li><li>O que meu treinador interior diria sobre meu desempenho?</li><li>O que vou praticar de forma diferente com base no que aprendi hoje?</li><li>Do que me orgulho, independentemente do resultado?</li></ol><h3 id="reflexao-semanal" tabindex="-1">Reflexão Semanal <a class="header-anchor" href="#reflexao-semanal" aria-label="Permalink to &quot;Reflexão Semanal&quot;">​</a></h3><ol><li>Que padrão estou observando na minha prática?</li><li>Estou praticando aquilo com que tenho dificuldade em competições?</li><li>Meu jogo mental está melhorando?</li><li>Estou gostando do processo?</li><li>O que precisa mudar na próxima semana?</li></ol><h3 id="reflexao-mensal" tabindex="-1">Reflexão Mensal <a class="header-anchor" href="#reflexao-mensal" aria-label="Permalink to &quot;Reflexão Mensal&quot;">​</a></h3><ol><li>Estou mais perto dos meus objetivos do que no mês passado?</li><li>O que está funcionando na minha abordagem de treinamento?</li><li>O que não está funcionando?</li><li>Preciso ajustar meus objetivos?</li><li>Do que quero me lembrar deste mês?</li></ol><hr><h2 id="tips-for-effective-diary-keeping" tabindex="-1">Tips for Effective Diary Keeping <a class="header-anchor" href="#tips-for-effective-diary-keeping" aria-label="Permalink to &quot;Tips for Effective Diary Keeping&quot;">​</a></h2><h3 id="_1-write-immediately-after-training" tabindex="-1">1. Write Immediately After Training <a class="header-anchor" href="#_1-write-immediately-after-training" aria-label="Permalink to &quot;1. Write Immediately After Training&quot;">​</a></h3><p><strong>Why:</strong> Details are fresh, emotions are real, insights are clear</p><p><strong>How:</strong> Keep diary in your bag, set 10 minutes aside after each session</p><h3 id="_2-be-honest-not-perfect" tabindex="-1">2. Be Honest, Not Perfect <a class="header-anchor" href="#_2-be-honest-not-perfect" aria-label="Permalink to &quot;2. Be Honest, Not Perfect&quot;">​</a></h3><p><strong>Don&#39;t:</strong> Write what you think you should write <strong>Do:</strong> Write what actually happened and how you really felt</p><h3 id="_3-focus-on-process-not-just-results" tabindex="-1">3. Focus on Process, Not Just Results <a class="header-anchor" href="#_3-focus-on-process-not-just-results" aria-label="Permalink to &quot;3. Focus on Process, Not Just Results&quot;">​</a></h3><p><strong>Don&#39;t:</strong> &quot;Missed 7 out of 10 shots - terrible&quot; <strong>Do:</strong> &quot;Missed 7 out of 10 shots - noticed I was rushing my routine, will slow down next time&quot;</p><h3 id="_4-look-for-patterns" tabindex="-1">4. Look for Patterns <a class="header-anchor" href="#_4-look-for-patterns" aria-label="Permalink to &quot;4. Look for Patterns&quot;">​</a></h3><p>Review your diary weekly to spot:</p><ul><li>Recurring technical issues</li><li>Mental game patterns</li><li>Energy/performance correlations</li><li>What conditions you perform best in</li></ul><h3 id="_5-celebrate-progress" tabindex="-1">5. Celebrate Progress <a class="header-anchor" href="#_5-celebrate-progress" aria-label="Permalink to &quot;5. Celebrate Progress&quot;">​</a></h3><p><strong>Every month:</strong> Read entries from 3 months ago <strong>Notice:</strong> How much you&#39;ve improved <strong>Acknowledge:</strong> The work you&#39;ve put in</p><hr><h2 id="diario-digital-vs-diario-de-papel" tabindex="-1">Diário digital vs. diário de papel <a class="header-anchor" href="#diario-digital-vs-diario-de-papel" aria-label="Permalink to &quot;Diário digital vs. diário de papel&quot;">​</a></h2><h3 id="digital-google-docs-sheets-notion-aplicativos" tabindex="-1">Digital (Google Docs/Sheets, Notion, Aplicativos) <a class="header-anchor" href="#digital-google-docs-sheets-notion-aplicativos" aria-label="Permalink to &quot;Digital (Google Docs/Sheets, Notion, Aplicativos)&quot;">​</a></h3><p><strong>Prós:</strong></p><ul><li>Fácil de pesquisar entradas anteriores</li><li>Pode adicionar fotos/vídeos</li><li>Carimbos de data automáticos</li><li>Pode compartilhar com o treinador</li><li>Sempre acessível por telefone</li></ul><p><strong>Contras:</strong></p><ul><li>Tempo de tela</li><li>Pode parecer impessoal</li><li>Distrações causadas por notificações</li></ul><p><strong>Ideal para:</strong> Rastreamento detalhado de estatísticas, análise de padrões a longo prazo</p><h3 id="papel-caderno-modelos-impressos" tabindex="-1">Papel (Caderno, Modelos Impressos) <a class="header-anchor" href="#papel-caderno-modelos-impressos" aria-label="Permalink to &quot;Papel (Caderno, Modelos Impressos)&quot;">​</a></h3><p><strong>Prós:</strong> Conexão tátil e pessoal</p><ul><li>Sem distrações</li><li>Diagramas fáceis de esboçar</li><li>Ritual satisfatório</li><li>Melhor para reflexão</li></ul><p><strong>Contras:</strong></p><ul><li>Posso perder o caderno</li><li>Dificuldade em pesquisar entradas antigas</li><li>Não é fácil de compartilhar</li></ul><p><strong>Ideal para:</strong> Reflexões diárias, anotações imediatas após o treino</p><p><strong>Recomendação:</strong> Abordagem híbrida - papel para registros diários, digital para resumos e estatísticas mensais.</p><hr><h2 id="sample-entries" tabindex="-1">Sample Entries <a class="header-anchor" href="#sample-entries" aria-label="Permalink to &quot;Sample Entries&quot;">​</a></h2><h3 id="example-good-training-entry" tabindex="-1">Example: Good Training Entry <a class="header-anchor" href="#example-good-training-entry" aria-label="Permalink to &quot;Example: Good Training Entry&quot;">​</a></h3><details class="details custom-block"><summary>Click to See Example</summary><p><strong>Date:</strong> March 15, 2024 <strong>Duration:</strong> 90 minutes <strong>Location:</strong> Club terrain <strong>Terrain:</strong> Hard <strong>Weather:</strong> Sunny, light wind</p><p><strong>Today&#39;s Intention:</strong> Improve pointing accuracy at 8m</p><p><strong>Technical Practice:</strong></p><ul><li>Pointing at 8m: 30 attempts, 18 within 20cm (60%)</li><li>Noticed I&#39;m more accurate when I take 3 breaths before throwing</li><li>Struggled when wind picked up - need to adjust for wind better</li></ul><p><strong>What Worked Well:</strong></p><ol><li>Pre-shot routine was consistent</li><li>Stayed calm after misses</li><li>Adjusted grip for hard terrain</li></ol><p><strong>Key Insight:</strong> My accuracy drops when I rush. Slowing down by 2 seconds improves success rate significantly.</p><p><strong>Mental Game:</strong></p><ul><li>Energy: 8/10</li><li>Focus: 7/10</li><li>Used Inner Coach after 3 bad throws - helped me reset</li></ul><p><strong>Tomorrow&#39;s Focus:</strong> Practice pointing in windy conditions, maintain slow routine</p></details><h3 id="example-good-competition-entry" tabindex="-1">Example: Good Competition Entry <a class="header-anchor" href="#example-good-competition-entry" aria-label="Permalink to &quot;Example: Good Competition Entry&quot;">​</a></h3><details class="details custom-block"><summary>Click to See Example</summary><p><strong>Date:</strong> March 20, 2024 <strong>Tournament:</strong> Regional Championship <strong>Format:</strong> Triples <strong>Final Placement:</strong> 5th of 16 teams</p><p><strong>Performance Analysis:</strong></p><ul><li>Technical: 7/10 - Pointing was solid, shooting was inconsistent</li><li>Mental: 8/10 - Stayed calm under pressure</li><li>Tactical: 6/10 - Made one bad decision in semi-final</li></ul><p><strong>Best Moment:</strong> Carreau in quarter-final to win 13-12</p><p><strong>Toughest Moment:</strong> Semi-final, 11-11, rushed a shot and missed badly</p><p><strong>Key Learning:</strong> When score is tight, I need to slow down even more, not speed up. My Inner Critic tried to take over (&quot;Don&#39;t mess this up!&quot;) but I caught it and used Inner Coach instead (&quot;You&#39;ve made this shot 100 times, trust your routine&quot;).</p><p><strong>For Next Competition:</strong> Practice pressure situations in training - simulate 11-11 scenarios</p></details><hr><h2 id="recursos-relacionados" tabindex="-1">Recursos relacionados <a class="header-anchor" href="#recursos-relacionados" aria-label="Permalink to &quot;Recursos relacionados&quot;">​</a></h2><ul><li><a href="/en/goal-template">Modelo para definição de metas</a> - Defina e acompanhe suas metas de melhoria</li><li><a href="/en/workshop">Workshop</a> - Sessões em grupo sobre jogo mental e reflexão</li><li><a href="/en/training-session">Sessão de Treinamento</a> - Prática estruturada com colegas</li><li><a href="/en/education/mental-strength">Força Mental</a> - Desenvolva a resiliência mental</li><li><a href="/en/education/mindfulness">Mindfulness</a> - Desenvolver a consciência e o foco</li></ul><hr><h2 id="quick-start-guide" tabindex="-1">Quick Start Guide <a class="header-anchor" href="#quick-start-guide" aria-label="Permalink to &quot;Quick Start Guide&quot;">​</a></h2><p><strong>New to diary keeping? Start here:</strong></p><p><strong>Week 1:</strong> Use Quick Daily Entry (5 minutes after each session) <strong>Week 2:</strong> Add one reflection prompt per entry <strong>Week 3:</strong> Try full Daily Training Entry <strong>Week 4:</strong> Do first Weekly Summary</p><p><strong>After one month:</strong> Add Monthly Summary and specific practice logs</p><hr><p>::: Aviso: Erros Comuns em Diários</p><ol><li><strong>Detalhado demais</strong> - Passar 30 minutos escrevendo e desistir depois de uma semana.</li><li><strong>Muito vago</strong> - &quot;Treinei hoje, foi razoável&quot; não ajuda a melhorar.</li><li><strong>Registre apenas as falhas</strong> - Comemore também as vitórias!</li><li><strong>Nunca revise</strong> - O poder está em ler as postagens anteriores.</li><li><strong>Esperar muito tempo</strong> - Escreva em até 30 minutos após terminar. :::</li></ol><hr><h2 id="download-templates" tabindex="-1">Download Templates <a class="header-anchor" href="#download-templates" aria-label="Permalink to &quot;Download Templates&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Copy-Paste Ready</p><p>All templates on this page are designed to be copied directly into:</p><ul><li>Microsoft Word</li><li>Google Docs</li><li>Microsoft Excel</li><li>Google Sheets</li><li>Notion</li><li>Evernote</li><li>Any note-taking app</li></ul><p>Simply select the template section you want, copy (Ctrl+C / Cmd+C), and paste into your preferred tool.</p></div><p><strong>Start with these three:</strong></p><ol><li>Daily Training Entry Template</li><li>Competition/Match Entry Template</li><li>Weekly Summary Template</li></ol><hr><p><strong>Melhor Momento:</strong></p><p><strong>Momento mais difícil:</strong></p><p><strong>Como eu respondi:</strong></p><hr><h3 id="mental-game-in-competition" tabindex="-1">Mental Game in Competition <a class="header-anchor" href="#mental-game-in-competition" aria-label="Permalink to &quot;Mental Game in Competition&quot;">​</a></h3><p><strong>Pressure Situations:</strong></p><p><strong>How I Managed Pressure:</strong></p><p><strong>Inner Critic Activity (1-10):</strong> _____ <strong>Inner Coach Activity (1-10):</strong> _____</p><p><strong>Mental Techniques Used:</strong></p><ul><li>[ ] 3-Breath Reset</li><li>[ ] Inner Coach Reframe</li><li>[ ] Mindful Awareness</li><li>[ ] Visualization</li><li>[ ] Routine Consistency</li><li>[ ] Other: ________</li></ul><hr><h3 id="principais-aprendizados" tabindex="-1">Principais Aprendizados <a class="header-anchor" href="#principais-aprendizados" aria-label="Permalink to &quot;Principais Aprendizados&quot;">​</a></h3><p><strong>Técnico:</strong></p><p><strong>Tático:</strong></p><p><strong>Mental:</strong></p><p><strong>Para a próxima competição:</strong></p><hr><h2 id="weekly-summary-template" tabindex="-1">Weekly Summary Template <a class="header-anchor" href="#weekly-summary-template" aria-label="Permalink to &quot;Weekly Summary Template&quot;">​</a></h2><h3 id="copy-this-section-each-week" tabindex="-1">Copy This Section Each Week <a class="header-anchor" href="#copy-this-section-each-week" aria-label="Permalink to &quot;Copy This Section Each Week&quot;">​</a></h3><hr><p><strong>Semana de:</strong> ________</p><h3 id="visao-geral-do-treinamento" tabindex="-1">Visão Geral do Treinamento <a class="header-anchor" href="#visao-geral-do-treinamento" aria-label="Permalink to &quot;Visão Geral do Treinamento&quot;">​</a></h3><p><strong>Total de horas de treinamento:</strong> _____ <strong>Número de sessões:</strong> _____ <strong>Horário da Competição:</strong> _____ <strong>Treinamento Mental:</strong> _____ minutos <strong>Treinamento Físico:</strong> _____ sessões</p><h3 id="progresso-semanal" tabindex="-1">Progresso Semanal <a class="header-anchor" href="#progresso-semanal" aria-label="Permalink to &quot;Progresso Semanal&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Área de Objetivo</th><th>Meta</th><th>Real</th><th>Progresso</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr><tr><td></td><td></td><td></td><td></td></tr></tbody></table><h3 id="vitorias-desta-semana" tabindex="-1">Vitórias desta semana <a class="header-anchor" href="#vitorias-desta-semana" aria-label="Permalink to &quot;Vitórias desta semana&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="desafios-desta-semana" tabindex="-1">Desafios desta semana <a class="header-anchor" href="#desafios-desta-semana" aria-label="Permalink to &quot;Desafios desta semana&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><h3 id="reconhecimento-de-padroes" tabindex="-1">Reconhecimento de Padrões <a class="header-anchor" href="#reconhecimento-de-padroes" aria-label="Permalink to &quot;Reconhecimento de Padrões&quot;">​</a></h3><p>(Que padrões estou percebendo na minha prática/desempenho?)</p><h3 id="foco-da-proxima-semana" tabindex="-1">Foco da próxima semana <a class="header-anchor" href="#foco-da-proxima-semana" aria-label="Permalink to &quot;Foco da próxima semana&quot;">​</a></h3><ol><li></li><li></li><li></li></ol><hr>',196)])])}]]);export{r as __pageData,i as default};
